--
-- Name: autenticar_usuario("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."autenticar_usuario"("p_dni" "text", "p_password" "text") RETURNS TABLE("id" "uuid", "nombre_completo" "text", "dni_username" "text", "correo_institucional" "text", "area" "text", "cargo_rol" "text", "especialidad" "text", "permisos_json" "jsonb", "es_administrador_presupuesto" boolean, "es_gerencia" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user usuarios_sistema%ROWTYPE;
BEGIN
  -- Buscar usuario activo con DNI + contraseña (bcrypt via pgcrypto)
  SELECT *
    INTO v_user
    FROM usuarios_sistema u
   WHERE u.dni_username = p_dni
     AND u.password_hash = crypt(p_password, u.password_hash)
     AND u.is_active = true
   LIMIT 1;

  -- Si no se encontró, retorna vacío (login fallido)
  IF v_user.id IS NULL THEN
    RETURN;
  END IF;

  -- Actualizar last_login
  UPDATE usuarios_sistema
     SET last_login = NOW()
   WHERE usuarios_sistema.id = v_user.id;

  -- Retornar datos del usuario (SIN password_hash)
  RETURN QUERY
  SELECT
    v_user.id,
    v_user.nombre_completo,
    v_user.dni_username,
    v_user.correo_institucional,
    v_user.area,
    v_user.cargo_rol,
    v_user.especialidad,
    v_user.permisos_json,
    v_user.es_administrador_presupuesto,
    v_user.es_gerencia;
END;
$$;


ALTER FUNCTION "public"."autenticar_usuario"("p_dni" "text", "p_password" "text") OWNER TO "postgres";

--
-- Name: importar_metrados_batch("jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."importar_metrados_batch"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  item jsonb;
  inserted_count integer := 0;
  new_metrado_id uuid;
  obrero_id uuid;
BEGIN
  FOR item IN SELECT * FROM jsonb_array_elements(payload)
  LOOP
    -- Insertar en registro_metrados
      id, fecha_ejecucion, frente_trabajo, bloque_sector, nivel_piso,
      cuadrilla, partida_id, snapshot_codigo, snapshot_descripcion,
      unidad, especialidad, elemento_desc, detalle_desc, acero_diametro,
      cantidad_elementos, medida_largo_area, medida_ancho_empalme,
      medida_alto_gancho, nro_repeticiones, resultado_parcial,
      resultado_total, created_at, origen_archivo, user_id, is_liberado
    ) VALUES (
      gen_random_uuid(),
      (item->>'fecha_ejecucion')::date,
      item->>'frente_trabajo',
      item->>'bloque_sector',
      item->>'nivel_piso',
      item->>'cuadrilla',
      (item->>'partida_id')::uuid,
      item->>'snapshot_codigo',
      item->>'snapshot_descripcion',
      item->>'unidad',
      item->>'especialidad',
      item->>'elemento_desc',
      item->>'detalle_desc',
      item->>'acero_diametro',
      (item->>'cantidad_elementos')::numeric,
      (item->>'medida_largo_area')::numeric,
      (item->>'medida_ancho_empalme')::numeric,
      (item->>'medida_alto_gancho')::numeric,
      (item->>'nro_repeticiones')::numeric,
      (item->>'resultado_parcial')::numeric,
      (item->>'resultado_total')::numeric,
      now(),
      item->>'origen_archivo',
      (item->>'user_id')::uuid,
      COALESCE((item->>'is_liberado')::boolean, false)
    )
    RETURNING id INTO new_metrado_id;

    -- Insertar obreros si existen
    IF item->'obreros_ids' IS NOT NULL THEN
      FOR obrero_id IN 
        SELECT (value::text)::uuid 
        FROM jsonb_array_elements_text(item->'obreros_ids')
      LOOP
        VALUES (new_metrado_id, obrero_id)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;

    inserted_count := inserted_count + 1;
  END LOOP;

  RETURN jsonb_build_object('inserted', inserted_count);
END;$$;


ALTER FUNCTION "public"."importar_metrados_batch"("payload" "jsonb") OWNER TO "postgres";

--
-- Name: reset_user_password("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reset_user_password"("p_admin_id" "uuid", "p_user_id" "uuid", "p_password_hash" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  es_admin boolean;
BEGIN
  SELECT
    is_active AND (
      cargo_rol = 'ADMIN'
      OR (permisos_json->>'acceso_admin')::boolean = true
    )
  INTO es_admin
  FROM usuarios_sistema
  WHERE id = p_admin_id;

  IF es_admin IS NOT TRUE THEN
    RAISE EXCEPTION 'No autorizado para resetear contraseñas';
  END IF;

  IF p_password_hash IS NULL OR length(p_password_hash) < 20 THEN
    RAISE EXCEPTION 'Hash inválido';
  END IF;

  UPDATE usuarios_sistema
  SET password_hash = p_password_hash
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usuario no encontrado';
  END IF;

  VALUES (p_admin_id, p_user_id);
END;
$$;


ALTER FUNCTION "public"."reset_user_password"("p_admin_id" "uuid", "p_user_id" "uuid", "p_password_hash" "text") OWNER TO "postgres";

