--
-- Name: vw_actividad_reciente; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."vw_actividad_reciente" AS
 SELECT "rm"."id",
    "rm"."created_at",
    "rm"."especialidad",
    "rm"."cuadrilla",
    "rm"."fecha_ejecucion",
    "rm"."resultado_total",
    "rm"."snapshot_descripcion",
    "rm"."frente_trabajo",
    "us"."nombre_completo" AS "autor_nombre",
    "us"."area" AS "autor_area"
   FROM ("public"."registro_metrados" "rm"
     LEFT JOIN "public"."usuarios_sistema" "us" ON (("rm"."user_id" = "us"."id")))
  WHERE ("rm"."created_at" >= ("now"() - '7 days'::interval))
  ORDER BY "rm"."created_at" DESC
 LIMIT 50;


ALTER VIEW "public"."vw_actividad_reciente" OWNER TO "postgres";

--
-- Name: vw_avance_diario; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."vw_avance_diario" AS
 SELECT "fecha_ejecucion" AS "fecha",
    "especialidad",
    "sum"("resultado_total") AS "metrado_dia",
    "count"("id") AS "registros",
    "count"(DISTINCT "cuadrilla") AS "cuadrillas_dia"
   FROM "public"."registro_metrados" "rm"
  WHERE (("fecha_ejecucion" >= (CURRENT_DATE - '14 days'::interval)) AND ("resultado_total" IS NOT NULL))
  GROUP BY "fecha_ejecucion", "especialidad"
  ORDER BY "fecha_ejecucion" DESC;


ALTER VIEW "public"."vw_avance_diario" OWNER TO "postgres";

--
-- Name: vw_kpis_dashboard; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."vw_kpis_dashboard" AS
 SELECT COALESCE("sum"("resultado_total"), (0)::numeric) AS "metrado_total",
    "count"(DISTINCT "partida_id") AS "partidas_activas",
    "count"(DISTINCT "cuadrilla") AS "cuadrillas_activas",
    "count"(DISTINCT "especialidad") AS "especialidades_activas",
    COALESCE("sum"(
        CASE
            WHEN ("fecha_ejecucion" >= "date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone)) THEN "resultado_total"
            ELSE (0)::numeric
        END), (0)::numeric) AS "metrado_semana",
    COALESCE("sum"(
        CASE
            WHEN (("fecha_ejecucion" >= ("date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone) - '7 days'::interval)) AND ("fecha_ejecucion" < "date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone))) THEN "resultado_total"
            ELSE (0)::numeric
        END), (0)::numeric) AS "metrado_semana_anterior",
    COALESCE(( SELECT "sum"(("cp"."cantidad_presupuestada" * "cp"."precio_unitario_base")) AS "sum"
           FROM "public"."catalogo_partidas" "cp"
          WHERE (("cp"."estado_activo" = true) AND ("cp"."es_agrupador" = false) AND ("cp"."cantidad_presupuestada" IS NOT NULL))), (0)::numeric) AS "presupuesto_total",
    "max"("created_at") AS "ultimo_registro"
   FROM "public"."registro_metrados" "rm"
  WHERE ("resultado_total" IS NOT NULL);


ALTER VIEW "public"."vw_kpis_dashboard" OWNER TO "postgres";

--
-- Name: vw_resumen_metrados_especialidad; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."vw_resumen_metrados_especialidad" AS
 SELECT "especialidad" AS "especialidad_nombre",
    "count"(DISTINCT "partida_id") AS "partidas_count",
    "sum"("resultado_total") AS "total_ejecutado",
    "sum"(
        CASE
            WHEN ("fecha_ejecucion" >= "date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone)) THEN "resultado_total"
            ELSE (0)::numeric
        END) AS "ejecutado_semana",
    COALESCE(( SELECT "sum"("cp2"."cantidad_presupuestada") AS "sum"
           FROM "public"."catalogo_partidas" "cp2"
          WHERE (("cp2"."especialidad" = "rm"."especialidad") AND ("cp2"."estado_activo" = true) AND ("cp2"."es_agrupador" = false))), (0)::numeric) AS "presupuestado_total",
    "count"("id") AS "registros_count"
   FROM "public"."registro_metrados" "rm"
  WHERE (("especialidad" IS NOT NULL) AND ("resultado_total" IS NOT NULL))
  GROUP BY "especialidad"
  ORDER BY ("sum"("resultado_total")) DESC;


ALTER VIEW "public"."vw_resumen_metrados_especialidad" OWNER TO "postgres";

--
-- Name: vw_top_cuadrillas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."vw_top_cuadrillas" AS
 SELECT "cuadrilla",
    "sum"("resultado_total") AS "metrado_semana",
    "count"("id") AS "registros",
    "count"(DISTINCT "especialidad") AS "especialidades",
    "count"(DISTINCT "fecha_ejecucion") AS "dias_activos",
    "max"("fecha_ejecucion") AS "ultimo_dia"
   FROM "public"."registro_metrados" "rm"
  WHERE (("fecha_ejecucion" >= "date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone)) AND ("cuadrilla" IS NOT NULL) AND ("resultado_total" IS NOT NULL))
  GROUP BY "cuadrilla"
  ORDER BY ("sum"("resultado_total")) DESC
 LIMIT 10;


ALTER VIEW "public"."vw_top_cuadrillas" OWNER TO "postgres";

